/// The extension IEs of `LoggedMDTNr-ExtIEs` (NGAP-IEs). IEs not defined here are kept in `unknown_ies`.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct LoggedMdtNrExtIes {
    /// `id-EarlyMeasurement` (id 360, Ignore, Optional)
    pub early_measurement: Option<EarlyMeasurement>,
    /// IEs this version of the specification does not define here, as received (id, criticality, encoded value).
    pub unknown_ies: Vec<rt::ie::RawIe>,
}

impl LoggedMdtNrExtIes {
    /// A value with the mandatory IEs given and every optional one absent.
    pub fn new() -> Self {
        Self {
            early_measurement: None,
            unknown_ies: Vec::new(),
        }
    }
}

impl rt::AperEncode for LoggedMdtNrExtIes {
    fn aper_encode(&self, w: &mut rt::BitWriter) -> rt::Result<()> {
        let mut ies: Vec<rt::ie::RawIe> = Vec::new();
        if let Some(x) = &self.early_measurement {
            ies.push(rt::ie::RawIe::new(360, rt::ie::Criticality::Ignore, x)?);
        }
        ies.extend(self.unknown_ies.iter().cloned());
        rt::ie::write_container(w, rt::Size::range(1, 65535), &ies)
    }
}

impl rt::AperDecode for LoggedMdtNrExtIes {
    fn aper_decode(r: &mut rt::BitReader<'_>) -> rt::Result<Self> {
        let mut s_early_measurement: Option<EarlyMeasurement> = None;
        let mut unknown_ies = Vec::new();
        for ie in rt::ie::read_container(r, rt::Size::range(1, 65535))? {
            match ie.id {
                360 => rt::ie::set_once(&mut s_early_measurement, 360, ie.decode()?)?,
                _ => unknown_ies.push(ie),
            }
        }
        Ok(Self {
            early_measurement: s_early_measurement,
            unknown_ies,
        })
    }
}

